def is_plain_name(name: str) -> bool:
    """True when name is one file name: non-empty, with no path separators, no '..' part, and not absolute."""
    pre name.char_count() > 0
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../a.txt") == False
    ex is_plain_name("sub/a.txt") == False
    ex is_plain_name("/etc/passwd") == False
    ex is_plain_name("..") == False
    if name.startswith("/"):
        return False
    if "/" in name or "\\" in name:
        return False
    if ".." in name:
        return False
    return True

def read_note(name: str) -> str | None uses fs:
    """Text of the file name inside the notes directory, or None when it is missing or unreadable."""
    pre is_plain_name(name) == True
    with fs = fs.sub("notes"):
        text = fs.read_text(name) else return None
        return text

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names that can be read from the notes directory, or '' when none can. Names that are not plain file names are skipped, so nothing outside notes is read."""
    for name in names:
        if is_plain_name(name):
            text = read_note(name)
            if text is not None:
                return text
    return ""
